      const v00 = h.m[j][i], v10 = h.m[j][i + 1], v01 = h.m[j + 1][i], v11 = h.m[j + 1][i + 1];
      const pts = [];
      if ((v00 <= 0) !== (v10 <= 0)) pts.push([nxp(i) + (0 - v00) / (v10 - v00) * (nxp(i + 1) - nxp(i)), nyp(j)]);
      if ((v01 <= 0) !== (v11 <= 0)) pts.push([nxp(i) + (0 - v01) / (v11 - v01) * (nxp(i + 1) - nxp(i)), nyp(j + 1)]);
      if ((v00 <= 0) !== (v01 <= 0)) pts.push([nxp(i), nyp(j) + (0 - v00) / (v01 - v00) * (nyp(j + 1) - nyp(j))]);
      if ((v10 <= 0) !== (v11 <= 0)) pts.push([nxp(i + 1), nyp(j) + (0 - v10) / (v11 - v10) * (nyp(j + 1) - nyp(j))]);
