    draw();

    function evc(ev) { var r = cv.getBoundingClientRect(); return { x:(ev.clientX-r.left)*W/r.width, y:(ev.clientY-r.top)*H/r.height, r:r }; }
    function pick(mx, my) { for (var i=0;i<N;i++){ var dx=nodes[i].x-mx, dy=nodes[i].y-my; if (dx*dx+dy*dy < Math.pow(nrad(nodes[i])+3,2)) return i; } return -1; }
    var drag = -1;
