        var rows = conn.map(function (e){ var other = e.a===h?e.bn:e.an;
          return '+ ' + defn(other) + ' <span style="color:'+CL.muted+'">E<sub>b</sub> '+e.eb.toFixed(2)+' eV · n'+e.n+'</span>'; }).join("<br>");
