    "#wbg-calc-root *{box-sizing:border-box}",
    "#wbg-calc-root .cc{display:grid;grid-template-columns:minmax(320px,420px) 1fr;gap:24px;align-items:start}",
    "@media(max-width:860px){#wbg-calc-root .cc{grid-template-columns:1fr}}",
    "#wbg-calc-root .card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:20px;box-shadow:0 1px 3px rgba(16,24,40,.05),0 1px 2px rgba(16,24,40,.04)}",
    "#wbg-calc-root h3{margin:0 0 4px;font-size:17px;font-weight:700;letter-spacing:-.01em}",
    "#wbg-calc-root h3 .sm{font-weight:500;font-size:14.0px;color:var(--muted);display:block;margin-top:2px}",
    "#wbg-calc-root label{display:block;font-size:14.0px;color:var(--muted);margin:14px 0 5px;font-weight:600;text-transform:none}",
    "#wbg-calc-root input[type=text],#wbg-calc-root input[type=password],#wbg-calc-root select,#wbg-calc-root textarea,#wbg-calc-root input[type=file]{width:100%;padding:9px 11px;border:1px solid var(--line);border-radius:9px;font:inherit;font-size:14px;background:#fcfcfd;color:var(--ink);transition:border-color .15s,box-shadow .15s}",
    "#wbg-calc-root input:focus,#wbg-calc-root select:focus,#wbg-calc-root textarea:focus{outline:none;border-color:var(--g);box-shadow:0 0 0 3px var(--gb)}",
    "#wbg-calc-root textarea{resize:vertical;min-height:54px}",
    "#wbg-calc-root .hint{font-size:14.0px;color:var(--muted);margin-top:4px;line-height:1.45}",
