    "#wbg-calc-root .checks input,#wbg-calc-root .cbx{width:auto;accent-color:var(--g)}",
    "#wbg-calc-root details{margin-top:14px;border-top:1px solid var(--line);padding-top:12px}",
    "#wbg-calc-root summary{cursor:pointer;font-size:14.0px;color:var(--gd);font-weight:700}",
    "#wbg-calc-root button.go{margin-top:18px;width:100%;background:linear-gradient(180deg,#1a9048,var(--g));color:#fff;border:0;border-radius:10px;padding:12px;font-size:15px;font-weight:700;cursor:pointer;box-shadow:0 1px 2px rgba(16,24,40,.15)}",
    "#wbg-calc-root button.go:hover{background:var(--gd)}",
    "#wbg-calc-root button.go:disabled{opacity:.55;cursor:not-allowed}",
    "#wbg-calc-root button.reset{margin-top:8px;width:100%;background:#fff;color:var(--gd);border:1px solid #d0d5dd;border-radius:10px;padding:9px;font-size:14.0px;font-weight:600;cursor:pointer}",
    "#wbg-calc-root button.reset:hover{background:#f3f6f4;border-color:var(--g)}",
