    "#wbg-calc-root .btn:hover{background:var(--gb)}",
    "#wbg-calc-root .eq{background:var(--gb);border:1px solid var(--gr);border-radius:10px;padding:10px 14px;font-size:14.0px;color:var(--gd);margin:0 0 18px;line-height:1.5}",
    "#wbg-calc-root .desc{font-size:14.0px;color:var(--gd);min-height:16px;margin-bottom:8px}",
