          const c = document.createElement("canvas");
          c.width = svgEl.width.baseVal.value * 2; c.height = svgEl.height.baseVal.value * 2;
          const g = c.getContext("2d");
          g.fillStyle = "#ffffff"; g.fillRect(0, 0, c.width, c.height);
