      const ttl = p.querySelector("#xan-title");
      if (ttl) ttl.innerHTML = "XANES — " + xdsub(sub(xpretty(key, Object.keys(pay).filter(k => k !== "__bulk__")))) + " in " + sub(host);
      const sel = p.querySelector("#xan-el"); if (!sel) return;
      const dels = defectEls(key);
