      if (dels.length) sel.value = dels[0];
      if (lp && [...sel.options].some(o => o.value === lp.el)) sel.value = lp.el;
      const ck0 = mp + "|" + key + "|" + sel.value + "|" + p.querySelector("#xan-edge").value + "|" + p.querySelector("#xan-q").value;
