/* WBG Data & citation tab v4 — the dataset-access card is gone entirely (data
   requests go through the Contact tab). Citation + changelog only.
   Root: #wbg-dataaccess-root. */
(() => {
  if (window.__wbgDataAccessInstalled) return;
  window.__wbgDataAccessInstalled = true;
  const esc = s => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;");
  const BIB = `@misc{wbg_defect_library,
  author        = {Rahman, Md Habibur},
  title         = {Kosmos: A Wide-Bandgap Semiconductor Defect Library},
  year          = {2026},
  howpublished  = {\\url{https://defect-informatics.github.io/wbg-v2}},
  note          = {interactive library: AlN (mp-661), 84 defects, six foundation MLFFs, all-DFT charged-defect DFT; campaign in progress}
}`;
  const LOG = [
    ["2026-07-28", "v2 — rebuilt on the all-DFT charged-defect campaign: AlN (mp-661) first host, six MLFFs, every payload regenerated from v2 data"],
    ["2026-07-19", "renamed Kosmos (κόσμος) — the ordered universe: the lattice as cosmos, the defect as the flaw in the order"],
    ["2026-07-18", "the library is named Chaos (\u03c7\u03ac\u03bf\u03c2) \u2014 the primordial gap, the void from which order emerges"],
    ["2026-07-18", "band-edge display gaps for TeF\u2086 and Sr\u2084Ta\u2082O\u2089 corrected to the MP-PBE values (a \u0393-point fallback had set them low); movies mark every defect part exactly (bulk-comparison); performance and typography pass"],
    ["2026-07-18", "relaxation movies for the full catalog (per-step energies and forces, EquFlashV2 + DFT); 4-pane viewer"],
    ["2026-07-18", "find-a-host wizard, compare-hosts, interactive level diagrams, carrier solver; the tool is named the imperfection"],
    ["2026-07-18", "contact form, live usage statistics, deep links, navigation reorganized; large-font pass"],
    ["2026-07-17", "FEFF10 XANES simulation panel in the Defect Explorer (live bulk / defect / reference spectra)"],
    ["2026-07-17", "level lookup, recipe cards, anneal calculator and experimental-anchors tabs"],
    ["2026-07-16", "dopability finalized on the corrected-lattice DFT chain (21/25 hosts); full-ecosystem audit"],
    ["2026-07-16", "growth-window library extended to 353 hosts with (T, p) maps"],
    ["2026-07-13", "defect calculator — upload any CIF, MLFF formation energies with MP competing phases"],
  ];
  const BTN = `background:#0e7490;color:#fff;border:none;border-radius:999px;padding:9px 26px;font-size:14.0px;font-weight:700;cursor:pointer;font-family:inherit`;
  function card(title, inner) {
    return `<div style="border:1px solid #dfe6ec;border-radius:12px;background:#fff;padding:18px 20px;margin-bottom:16px">
      <div style="font-size:15px;font-weight:750;color:#0f2a42;margin-bottom:10px">${title}</div>${inner}</div>`;
  }
  function render(root) {
    let log = "";
    for (const l of LOG) log += `<div style="display:flex;gap:14px;padding:5px 0;border-bottom:1px solid #f0f3f6"><div style="font-size:14.0px;color:#9aa3ae;white-space:nowrap;font-variant-numeric:tabular-nums">${l[0]}</div><div style="font-size:14.0px;color:#3d4650;line-height:1.45">${esc(l[1])}</div></div>`;
    root.innerHTML = `<style>#wbgda-bib, #wbgda-bib *{font-family:'IBM Plex Mono',ui-monospace,SFMono-Regular,Menlo,Consolas,monospace !important}</style><div style="max-width:960px;margin:18px auto 30px;padding:0 16px;color:#1a1d21;font-family:'Arial Narrow',Arial,sans-serif">
      <div style="text-align:center;margin-bottom:18px">
        <div style="font-size:20px;font-weight:750;color:#0f2a42">Data &amp; citation</div>
        <div style="font-size:14.0px;color:#5b6570;margin-top:4px">the dataset is shared with researchers on reasonable request via the Contact tab — and please cite the library in anything it supports.</div>
      </div>
      ${card("cite this library", `<pre id="wbgda-bib" style="background:#f6f9fb;border:1px solid #e7edf2;border-radius:10px;padding:16px 18px;font-family:'IBM Plex Mono',ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:14.0px;line-height:1.7;overflow-x:auto;margin:0;tab-size:2">${esc(BIB).replace(/^(\s*)([a-z]+)(\s*=)/gm, `$1<span style="color:#0e7490">$2</span>$3`).replace(/^@misc/, `<span style="color:#b45309">@misc</span>`).replace("howpublished</span>  =", "how published</span> =")}</pre><button data-copy="wbgda-bib" style="${BTN};margin-top:8px">copy to clipboard</button><div style="font-size:14.0px;color:#8a93a0;margin-top:8px">the journal reference will replace this entry once the manuscript is published.</div>`)}
      ${card("changelog", log)}
    </div>`;
    root.querySelectorAll("[data-copy]").forEach(b => b.addEventListener("click", () => {
      const t = b.dataset.copy === "wbgda-bib" ? BIB : root.querySelector("#" + b.dataset.copy).textContent;
      (navigator.clipboard ? navigator.clipboard.writeText(t) : Promise.reject()).then(
        () => { b.textContent = "copied ✓"; setTimeout(() => { b.textContent = "copy to clipboard"; }, 1600); },
        () => { window.prompt("copy:", t); });
    }));
  }
  function tryInject() {
    const root = document.getElementById("wbg-dataaccess-root");
    if (!root || root.dataset.done) return;
    root.dataset.done = "1";
    render(root);
  }
  new MutationObserver(() => tryInject()).observe(document.body, { childList: true, subtree: true });
  tryInject();
})();

