/* WBG deep links — ?tab=<id> opens that tab on load; every tab click keeps the
   URL in sync so any view can be shared. Exposes window.__wbgGoto(id). */
(() => {
  if (window.__wbgDeeplinkInstalled) return;
  window.__wbgDeeplinkInstalled = true;
  const NAV = {
    rankings: "Host Rankings", explorer: "Defect Explorer", landscape: "Defect landscape", dashb: "Defect Dashboard",
    profiles: "Host Profiles", rules: "Design Rules", doping: "Doping Windows",
    charged: "Charged levels", lookup: "Level Lookup", growth: "Growth Windows",
    recipes: "Recipe Cards", anneal: "Anneal Calculator", calculator: "Defect Calculator",
    anchors: "Experimental Anchors", about: "About & Authors", sitables: "Paper Tables",
    methods: "Methods & Constants", dataaccess: "Data Access", contact: "Contact",
    refs: "References",
    wizard: "Find a Host", compare: "Compare Hosts", leveldiag: "Level Diagrams", solver: "Carrier Solver"
  };
  window.__WBG_NAV = NAV;
  function findBtn(id) {
    const label = NAV[id];
    if (!label) return null;
    return [...document.querySelectorAll("button")].find(b => b.textContent.trim() === label) || null;
  }
  window.__wbgGoto = id => { const b = findBtn(id); if (b) b.click(); return !!b; };
  // restore from URL on load (poll until the nav has mounted)
  const want = new URLSearchParams(location.search).get("tab");
  if (want && NAV[want]) {
    let tries = 0;
    const iv = setInterval(() => {
      tries += 1;
      if (window.__wbgGoto(want) || tries > 60) clearInterval(iv);
    }, 400);
  }
  // keep the URL in sync with tab clicks
  document.addEventListener("click", e => {
    const b = e.target && e.target.closest ? e.target.closest("button") : null;
    if (!b) return;
    const lbl = b.textContent.trim();
    for (const id in NAV) {
      if (NAV[id] === lbl) {
        try {
          const u = new URL(location.href);
          u.searchParams.set("tab", id);
          history.replaceState(null, "", u);
        } catch (err) {}
        try {
          const tp = document.getElementById("wbg-trajm-panel"); if (tp) tp.remove();
          const xp = document.getElementById("wbg-xanes-panel"); if (xp) xp.remove();
          const hp = document.getElementById("wbg-hoverprofile"); if (hp) hp.remove();
        } catch (err) {}
        return;
      }
    }
  }, true);
})();

