/* WBG report-an-issue flag — floating pill (bottom-left) that opens the Contact
   tab prefilled with the current deep-link URL, so users can flag any entry. */
(() => {
  if (window.__wbgReportInstalled) return;
  window.__wbgReportInstalled = true;
  function install() {
    if (document.getElementById("wbg-report-flag")) return;
    if (!document.querySelector("#wbg-contact-root, button")) return;
    const b = document.createElement("button");
    b.id = "wbg-report-flag";
    b.textContent = "⚑ report an issue";
    b.style.cssText = "position:fixed;left:16px;bottom:16px;z-index:5000;background:#fff;color:#5b6570;" +
      "border:1px solid #dfe6ec;border-radius:999px;padding:7px 15px;font-size:14.0px;font-weight:600;" +
      "cursor:pointer;box-shadow:0 3px 12px rgba(12,42,66,.10);opacity:.88;font-family:inherit;transition:opacity .15s";
    b.addEventListener("mouseenter", () => { b.style.opacity = "1"; });
    b.addEventListener("mouseleave", () => { b.style.opacity = ".88"; });
    b.addEventListener("click", () => {
      window.__wbgContactPrefill = {
        topic: "Bug or data issue",
        msg: "regarding: " + location.href + "\n\n(describe what looks wrong — which host, defect, number or figure?)"
      };
      const cr = document.getElementById("wbg-contact-root");
      if (cr) { cr.dataset.done = ""; cr.innerHTML = ""; }
      if (window.__wbgGoto) window.__wbgGoto("contact");
    });
    document.body.appendChild(b);
  }
  new MutationObserver(() => install()).observe(document.body, { childList: true, subtree: true });
  install();
})();

