  const USUB = { "0": "₀", "1": "₁", "2": "₂", "3": "₃", "4": "₄", "5": "₅", "6": "₆", "7": "₇", "8": "₈", "9": "₉" };
  const usub = s => String(s).replace(/([A-Za-z\)])(\d+)/g, (m, c, d) => c + d.split("").map(x => USUB[x] || x).join(""));
